CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, full_name VARCHAR(120) NOT NULL, phone VARCHAR(30) NOT NULL DEFAULT '', address TEXT, role VARCHAR(20) NOT NULL DEFAULT 'member', active INTEGER NOT NULL DEFAULT 1, recovery_hash VARCHAR(255) NOT NULL, session_version INTEGER NOT NULL DEFAULT 1, created_at VARCHAR(19) NOT NULL);
CREATE TABLE organizations (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE types (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(120) NOT NULL UNIQUE, price DECIMAL(10,2) NOT NULL DEFAULT 0);
CREATE TABLE records (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,org_id INTEGER NOT NULL,type_id INTEGER NOT NULL,weight DECIMAL(12,3) NOT NULL,price DECIMAL(10,2) NOT NULL,record_date VARCHAR(10) NOT NULL,note TEXT,image VARCHAR(100),status VARCHAR(20) NOT NULL DEFAULT 'pending',review_note VARCHAR(255) NOT NULL DEFAULT '',reviewer_id INTEGER,created_at VARCHAR(19) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(type_id) REFERENCES types(id),FOREIGN KEY(reviewer_id) REFERENCES users(id));
CREATE TABLE contents (id INTEGER PRIMARY KEY AUTOINCREMENT,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,image VARCHAR(100),publish_at VARCHAR(19),expire_at VARCHAR(19),active INTEGER NOT NULL DEFAULT 1,created_at VARCHAR(19) NOT NULL);
CREATE TABLE reports (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,message TEXT NOT NULL,is_read INTEGER NOT NULL DEFAULT 0,reply TEXT,created_at VARCHAR(19) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE goals (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,month VARCHAR(7) NOT NULL,target DECIMAL(12,3) NOT NULL,UNIQUE(user_id,month),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE attempts (id INTEGER PRIMARY KEY AUTOINCREMENT,bucket VARCHAR(64) NOT NULL,attempted_at INTEGER NOT NULL);
CREATE INDEX idx_attempt ON attempts(bucket,attempted_at);
CREATE INDEX idx_record_user ON records(user_id,record_date);
CREATE INDEX idx_record_status ON records(status,record_date);
